/* ===== The mark, as pixels rather than as a file ==========================

   THE BUG THIS EXISTS TO FIX, which was already in the cards and the Studio
   before the reels ever drew a logo.

   Loading assets/brand/mark.svg into an Image and drawing it on a canvas
   TAINTS that canvas when the page is opened as a local file. Chromium gives
   every file:// document its own opaque origin, so the site's own logo is
   cross-origin to the site. A tainted canvas refuses toDataURL, toBlob,
   getImageData and captureStream — which is to say every way this site has
   of producing a card, a still or a reel.

   Over http that never happens, so it never showed up in any harness, and
   the one configuration it breaks is the one this site is built for: a
   folder of files on somebody\u2019s own Mac, opened without a server.

   A data: URI is same-origin everywhere, including file://. So the mark is
   carried here as 256px of PNG instead of being fetched. It is drawn at 88px
   on a card and 67px on a reel, so 256 is more resolution than any output
   uses, and the file is a twelfth the size of the SVG it replaces. The SVG
   stays the source of truth and is still what the pages show in <img>; this
   is the canvas copy.

   Regenerated by rebuilding from assets/brand/mark.svg if the mark changes. */

(function () {
  "use strict";
  var URI = "data:image/png;base64,";
  var IMG = null, TRIED = false, WAIT = null;
  /* one Image for the whole page, loaded once, awaited rather than hoped for */
  function ready() {
    if (IMG || TRIED) return Promise.resolve(IMG);
    if (WAIT) return WAIT;
    WAIT = new Promise(function (done) {
      var im = new Image();
      im.onload = function () { IMG = im; TRIED = true; done(im); };
      im.onerror = function () { TRIED = true; done(null); };
      im.src = URI;
    });
    return WAIT;
  }
  ready();
  window.NMark = { uri: URI, ready: ready,
                   get: function () { return IMG; } };
})();
